window.addEventListener("DOMContentLoaded", function () {
   document.querySelector("#fetchQuotesBtn").addEventListener("click", function () {

      // Get values from drop-downs
      const topicDropdown = document.querySelector("#topicSelection");
      const selectedTopic = topicDropdown.options[topicDropdown.selectedIndex].value;
      const countDropdown = document.querySelector("#countSelection");
      const selectedCount = countDropdown.options[countDropdown.selectedIndex].value;

      // Get and display quotes
      fetchQuotes(selectedTopic, selectedCount);      
   });
});

function showAnonymousQuotes(count) {
   let html = "<ol>";
   for (let c = 1; c <= count; c++) {
      html += `<li>Quote ${c} - Anonymous</li>`;
   }
   html += "</ol>";

   const quotes = document.querySelector("#quotes");
   quotes.innerHTML = html;
}

function fetchQuotes(topic, count) {
   const endpoint = "https://wp.zybooks.com/quotes.php";
   const queryString = `topic=${topic}&count=${count}`;
   const url = `${endpoint}?${queryString}`;

   const xhr = new XMLHttpRequest();
   xhr.addEventListener("load", responseReceivedHandler);
   xhr.responseType = "json";
   xhr.open("GET", url);
   xhr.send();
}

function responseReceivedHandler() {
   const quotes = document.querySelector("#quotes");
   if (this.status === 200) {
      if (this.response.error) {
         quotes.innerHTML = `<p>${this.response.error}</p>`;
      } 
      else {
         let html = "<ol>";
         for (let quoteItem of this.response) {
            html += `<li>${quoteItem.quote} - ${quoteItem.source}</li>`;
         }
         html += "</ol>";

         quotes.innerHTML = html;
      }
   } 
   else {
      quotes.innerHTML = "<p>Quote API is unavailable.</p>";
   }
}

