QUnit.test('Test XMLHttpRequest addEventListener() method', function (assert) {

   const mockXhr = {
      open(requestType, url) { },
      send() { },
      addEventListener(event, handler) {
         testAddEventListener(event, handler);
      },
      onload: null
   }

   let funcCalled = false;

   const mockResponseReceivedHandler = function(xhr) {
      funcCalled = true;
   } 

   responseReceivedHandler = mockResponseReceivedHandler;

   const testAddEventListener = function(event, handler) {
      funcCalled = true;
      assert.equal(event, 'load', 'Call addEventListener() with "load" event');
      assert.ok(handler == mockResponseReceivedHandler, 'Call addEventListener() with responseReceivedHandler()');
   }

   window.XMLHttpRequest = function() {
      return mockXhr;
   };

   const topic = 'love';
   const count = 3;
   fetchQuotes(topic, count);

   // Student can set onload property or call addEventListener("load")
   if (mockXhr.onload !== null) {
      assert.equal(typeof mockXhr.onload, 'function', 'onload set to a function');

      // Call the onload event handler to verify it is calling our mock 
      mockXhr.onload();
      assert.ok(funcCalled, 'onload event handler calls responseReceivedHandler()');
   }
   else {
      assert.ok(funcCalled, 'XMLHttpRequest addEventListener() is called');
   }

});

