QUnit.test('Test responseReceivedHandler() with humor quote', function (assert) {

   const ajaxResponse = {
      status: 200,
      response: [
         {
            quote: "Outside of a dog, a book is man's best friend. Inside of a dog it's too dark to read",
            source: 'Groucho Marx'
         }
      ]
   };

   assert.ok(typeof responseReceivedHandler === 'function', 'responseReceivedHandler() is defined');
   assert.strictEqual(responseReceivedHandler.length, 0, 'responseReceivedHandler() has no parameters');

   responseReceivedHandler.call(ajaxResponse);

   let html = '<ol>';
   for (let quote of ajaxResponse.response) {
      html += `<li>${quote.quote} - ${quote.source}</li>`;
   }
   html += '</ol>';

   const quotes = document.querySelector("#quotes");
   assert.equal(quotes.innerHTML.trim(), html, 'innerHTML of <div> is correct');
});

